# Deduplicate
seen = set()
unique = []
for w in words:
    k = w["Word"].lower()
    if k not in seen:
        seen.add(k)
        unique.append(w)

print(f"Tier 2: {len(unique)} unique words")
with open(r"scripts\toeic_tier2.json","w",encoding="utf-8") as f:
    json.dump(unique, f, ensure_ascii=False, indent=2)
print("Tier 2 saved.")
